import{_ as a,P as o,d as i,e as n,y as s,q as r}from"./chunks/framework.D7CAgLCq.js";const f=JSON.parse('{"title":"Each task is feasible; the combined plan may not be","description":"Resources must be available together at the required place and time.","frontmatter":{"title":"Each task is feasible; the combined plan may not be","description":"Resources must be available together at the required place and time."},"headers":[],"relativePath":"en/concepts/joint-feasibility.md","filePath":"en/concepts/joint-feasibility.md"}'),l={name:"en/concepts/joint-feasibility.md"};function c(d,e,h,p,b,u){const t=o("JointExplorer");return i(),n("div",null,[e[0]||(e[0]=s('<h1 id="each-task-is-feasible-the-combined-plan-may-not-be" tabindex="-1">Each task is feasible; the combined plan may not be <a class="header-anchor" href="#each-task-is-feasible-the-combined-plan-may-not-be" aria-label="Permalink to &quot;Each task is feasible; the combined plan may not be&quot;">​</a></h1><p>The book gives two tasks, each requiring one full unit of capacity in a time slot. Both must finish by the end of period one. Period-one capacity is one. Either task is feasible alone; <strong>the pair has no schedule satisfying the original deadlines</strong>.</p><h2 id="capacity-and-timing-are-both-conditions" tabindex="-1">Capacity and timing are both conditions <a class="header-anchor" href="#capacity-and-timing-are-both-conditions" aria-label="Permalink to &quot;Capacity and timing are both conditions&quot;">​</a></h2><p>Increasing period-one capacity to two makes the pair feasible in the model. Validly moving one deadline to period two also works if that period has one unit of capacity. Adding capacity only in period two while retaining both original deadlines does not repair the missed deadline.</p><p>These alternatives change different conditions. A later deadline cannot be silently inserted after failure and counted as success against the original plan. In a real project, capacity, demand, permission to reschedule, and consequences for affected people require evidence of their own.</p><h2 id="beyond-total-hours-usable-continuous-blocks" tabindex="-1">Beyond total hours: usable continuous blocks <a class="header-anchor" href="#beyond-total-hours-usable-continuous-blocks" aria-label="Permalink to &quot;Beyond total hours: usable continuous blocks&quot;">​</a></h2><p><a href="/xi-kari-skill/handbook/en/theory/part-07.html#section-7-3-9">§7.3.9</a> adds a feasibility condition for tasks that depend on continuous time. The same total hours can correspond to very different continuous blocks of available time. Responsibilities as a default contact, being on call, and filling in at short notice can cut up the uninterrupted time needed for study, work, rest, or preparing to exit, even if they are rarely actually invoked.</p><p><strong>Teaching example:</strong> An exercise must be completed in two uninterrupted hours. One person has a fixed two-hour block. Another also has two hours in total, but only in unpredictable short gaps. Equal totals do not make the two plans equally feasible. Record the length and predictability of the usable blocks separately; do not convert continuity into hours or add it to clock time already recorded.</p><h2 id="a-second-problem-one-action-under-incomplete-information" tabindex="-1">A second problem: one action under incomplete information <a class="header-anchor" href="#a-second-problem-one-action-under-incomplete-information" aria-label="Permalink to &quot;A second problem: one action under incomplete information&quot;">​</a></h2><p>F3 concerns a related but distinct issue. Suppose the observation leaves two possible states. The acceptable action set is {left} in one and {right} in the other. Each state has an acceptable action, but their intersection is empty: no single action selected from this observation is acceptable in both.</p><p>If both states allow a validly authorized preservation action, the intersection can become nonempty without fully identifying the state. An additional observation may also help, but its cost, timeliness, risk, and availability must be assessed. Investigation is not automatically free or useful.</p><div class="xk-table"><table><thead><tr><th>Claim</th><th>Required check</th></tr></thead><tbody><tr><td>Every task can be done separately</td><td>Each task’s own constraints.</td></tr><tr><td>All tasks can be done together</td><td>Their combined resource and deadline constraints.</td></tr><tr><td>One action works despite uncertainty</td><td>A common acceptable action across the listed compatible states.</td></tr></tbody></table></div><p>The formal statements establish consequences of supplied constraints. They do not certify that real resources exist or that a named actor has permission to use them. Acceptable-action sets must already incorporate the task’s required protection and valid authority.</p><p>Read <a href="/xi-kari-skill/handbook/en/theory/appendix-c.html#section-c-12">C.12</a>, <a href="/xi-kari-skill/handbook/en/theory/part-07.html#section-7-3-9">§7.3.9</a>, <a href="./chain.html">causal chains</a>, and <a href="./responsibility.html">responsibility</a>.</p><h2 id="explore-the-teaching-model" tabindex="-1">Explore the teaching model <a class="header-anchor" href="#explore-the-teaching-model" aria-label="Permalink to &quot;Explore the teaching model&quot;">​</a></h2>',15)),r(t)])}const y=a(l,[["render",c]]);export{f as __pageData,y as default};
